function instructor_student_check(array $identity,string $area): array {if(($identity['type']??'')!=='ALUNO')return [false,'Este leitor por ala aceita somente QR de alunos/integrantes.'];$st=db()->prepare("SELECT e.instrument,e.status,c.status card_status,c.valid_until FROM enrollments e LEFT JOIN student_cards c ON c.enrollment_id=e.id WHERE e.id=? AND e.deleted_at IS NULL");$st->execute([$identity['id']]);$r=$st->fetch();if(!$r||$r['status']!=='APROVADA')return [false,'Aluno não está com matrícula aprovada.'];if($r['instrument']!==$area)return [false,'Este aluno pertence à ala '.$r['instrument'].'. O leitor atual é '.$area.'.'];if(($r['card_status']??'')!=='ATIVA')return [false,'Carteirinha não está ativa.'];if(($r['valid_until']??'0000-00-00')<date('Y-m-d'))return [false,'Carteirinha vencida.'];return [true,''];}
if($_SERVER['REQUEST_METHOD']==='POST'){$ajax=($_POST['ajax']??'')==='1';if($ajax)header('Content-Type:application/json; charset=UTF-8');try{csrf_check();$action=$_POST['action']??'';if(!$authorized)throw new RuntimeException('Acesso à ala não autorizado.');$control=attendance_area_control($eventId,$area);
