  elseif($action==='close_entry'){if($phase!=='ENTRADA')throw new RuntimeException('A entrada não está aberta.');$pdo->prepare("UPDATE attendance_area_controls SET phase='INTERVALO',entry_closed_at=?,last_instructor_id=?,updated_at=? WHERE event_id=? AND area=?")->execute([$now,(int)$u['id'],$now,$eventId,$area]);$m='Entrada encerrada. Abra a SAÍDA somente no final.';}
  elseif($action==='open_exit'){if($phase!=='INTERVALO')throw new RuntimeException('Encerre a entrada antes de abrir a saída.');$pdo->prepare("UPDATE attendance_area_controls SET phase='SAIDA',exit_opened_at=?,last_instructor_id=?,updated_at=? WHERE event_id=? AND area=?")->execute([$now,(int)$u['id'],$now,$eventId,$area]);$m='Leitura de SAÍDA aberta.';}
  else{if($phase!=='SAIDA')throw new RuntimeException('A saída não está aberta.');$pdo->prepare("UPDATE attendance_area_controls SET phase='CONCLUIDO',exit_closed_at=?,last_instructor_id=?,updated_at=? WHERE event_id=? AND area=?")->execute([$now,(int)$u['id'],$now,$eventId,$area]);$_SESSION['instructor_flash']='Controle concluído. Lista de presentes e ausentes gerada automaticamente.';header('Location: relatorio.php?event_id='.$eventId.'&area='.urlencode($area));exit;}
  igo('presenca.php?event_id='.$eventId.'&area='.urlencode($area),$m);
 }
 if($action==='scan'){$control=attendance_area_control($eventId,$area);$phase=$control['phase'];if(!in_array($phase,['ENTRADA','SAIDA'],true))throw new RuntimeException('A leitura não está aberta. Use os botões de ENTRADA/SAÍDA.');$checkType=$phase==='ENTRADA'?'ENTRADA':'SAIDA';$payload=trim((string)($_POST['payload']??''));$number=trim((string)($_POST['number']??''));$identity=$payload!==''?attendance_identity_from_payload($payload):null;if(!$identity&&$number!=='')$identity=attendance_identity_from_number($number);if(!$identity)throw new RuntimeException('QR ou matrícula não reconhecido.');[$ok,$why]=instructor_student_check($identity,$area);if(!$ok)throw new RuntimeException($why);if($checkType==='SAIDA'){$st=$pdo->prepare("SELECT scanned_at FROM attendance_checks WHERE event_id=? AND person_type='ALUNO' AND person_id=? AND check_type='ENTRADA'");$st->execute([$eventId,$identity['id']]);if(!$st->fetchColumn())throw new RuntimeException('Não há ENTRADA registrada para este aluno.');}$st=$pdo->prepare("SELECT scanned_at FROM attendance_checks WHERE event_id=? AND person_type='ALUNO' AND person_id=? AND check_type=?");$st->execute([$eventId,$identity['id'],$checkType]);$existing=$st->fetchColumn();if($existing){$response=['ok'=>true,'duplicate'=>true,'message'=>$checkType.' já registrada às '.date('H:i',strtotime((string)$existing)).'.','person'=>$identity,'check_type'=>$checkType];}else{$pdo->prepare("INSERT INTO attendance_checks(event_id,person_type,person_id,area,check_type,scanned_at,scan_method,instructor_id) VALUES(?,'ALUNO',?,?,?,?,?,?)")->execute([$eventId,$identity['id'],$area,$checkType,now_iso(),$payload!==''?'QR':'MANUAL',(int)$u['id']]);$response=['ok'=>true,'duplicate'=>false,'message'=>$checkType.' REGISTRADA','person'=>$identity,'check_type'=>$checkType,'time'=>date('H:i')];}if($ajax){echo json_encode($response,JSON_UNESCAPED_UNICODE);exit;}}
 }catch(Throwable $e){if($ajax){http_response_code(400);echo json_encode(['ok'=>false,'message'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);exit;}$err=$e->getMessage();}}
$control=$authorized?attendance_area_control($eventId,$area):null;$entryCount=$exitCount=0;$recent=[];if($authorized){$st=$pdo->prepare("SELECT COUNT(*) FROM attendance_checks WHERE event_id=? AND area=? AND person_type='ALUNO' AND check_type='ENTRADA'");$st->execute([$eventId,$area]);$entryCount=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT COUNT(*) FROM attendance_checks WHERE event_id=? AND area=? AND person_type='ALUNO' AND check_type='SAIDA'");$st->execute([$eventId,$area]);$exitCount=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT ac.*,e.student_name,e.preferred_name,e.registration_number FROM attendance_checks ac JOIN enrollments e ON e.id=ac.person_id WHERE ac.event_id=? AND ac.area=? AND ac.person_type='ALUNO' ORDER BY ac.scanned_at DESC LIMIT 20");$st->execute([$eventId,$area]);$recent=$st->fetchAll();}
