(()=>{const csrf=<?=json_encode(csrf_token())?>,eventId=<?=$eventId?>,area=<?=json_encode($area)?>,video=document.getElementById('qrVideo'),result=document.getElementById('scanResult'),msg=document.getElementById('cameraMessage');let stream=null,detector=null,running=false,last='',lastAt=0;function esc(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function send(data){const body=new URLSearchParams({csrf,action:'scan',ajax:'1',event_id:String(eventId),area,...data});try{const r=await fetch('presenca.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||'Falha');const n=j.person.preferred||j.person.name;result.className='scan-result success';result.innerHTML='<strong>'+esc(j.message)+'</strong><b>'+esc(n)+'</b><span>'+esc(j.person.number+' · '+area)+'</span>';if(navigator.vibrate)navigator.vibrate(j.duplicate?[80]:[100,60,100]);}catch(e){result.className='scan-result failure';result.innerHTML='<strong>NÃO REGISTRADO</strong><span>'+esc(e.message)+'</span>';if(navigator.vibrate)navigator.vibrate([250]);}}async function loop(){if(!running||!detector)return;try{const codes=await detector.detect(video);if(codes.length){const raw=codes[0].rawValue||'';const now=Date.now();if(raw&&(raw!==last||now-lastAt>3000)){last=raw;lastAt=now;await send({payload:raw});}}}catch(e){}setTimeout(loop,300)}document.getElementById('startCamera').onclick=async()=>{try{if(!('BarcodeDetector'in window))throw new Error('Leitura automática não disponível. Use Chrome/Edge atualizado ou matrícula manual.');detector=new BarcodeDetector({formats:['qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=stream;await video.play();running=true;msg.textContent='Câmera ativa — aproxime o QR.';loop();}catch(e){msg.textContent=e.message}};document.getElementById('stopCamera').onclick=()=>{running=false;if(stream)stream.getTracks().forEach(t=>t.stop());video.srcObject=null;msg.textContent='Câmera parada.'};document.getElementById('manualPresence').onsubmit=async e=>{e.preventDefault();const number=document.getElementById('manualNumber').value.trim();if(number)await send({number})};})();</script><?php endif;?>
